description:
The following example runs in Linux without the problem of continual CPU occupation.

Here's the reprex:

```R
library(shiny)
library(websocket)

ui <- fluidPage(
  textInput("textline", "Message"),
  actionButton("send", "Send"),
  verbatimTextOutput("reply")
)

server <- function(input, output, session) {
  rv <- reactiveValues(
    ready = FALSE,
    response = NULL
  )

  ws <- WebSocket$new("ws://echo.websocket.org/", autoConnect = FALSE)
  ws$onOpen(function(event) {
    cat("Connection opened\n")
    rv$ready <- TRUE
  })
  ws$onMessage(function(event) {
    rv$response <- event$data
  })
  ws$onClose(function(event) {
    cat("Client disconnected with code ", event$code,
      " and reason ", event$reason, "\n", sep = "")
    rv$ready <- FALSE
  })
  ws$onError(function(event) {
    cat("Client failed to connect: ", event$message, "\n")
    rv$ready <- FALSE
  })
  ws$connect()

  output$reply <- renderText({
    req(rv$response)
    paste0("Message received: ", rv$response, "\n")
  })

  observeEvent(input$send, {
    req(input$textline)

    if (rv$ready) {
      ws$send(input$textline)
      updateTextInput(session, inputId = "textline", label = "Message", value = "")
    }

  })
}

app <- shinyApp(ui, server)

runApp(app)
```

I'm using the example code:
```r
library(websocket)

ws <- WebSocket$new("ws://echo.websocket.org/", autoConnect = FALSE)
ws$onOpen(function(event) {
  cat("Connection opened\n")
})
ws$onMessage(function(event) {
  cat("Client got msg: ", event$data, "\n")
})
ws$onClose(function(event) {
  cat("Client disconnected with code ", event$code,
    " and reason ", event$reason, "\n", sep = "")
})
ws$onError(function(event) {
  cat("Client failed to connect: ", event$message, "\n")
})
ws$connect()
```
and it just doesn't work, the process exists right away without anything getting printed to the console

On Windows, if the user's `~/.Renviron` file has `MAKEFLAGS=-j4`, then installation will fail. (The same is probably true if the system Renviron file has that setting.)

